OPENQASM 3.0;
include "stdgates.inc";
bit[2] meas;
qubit[1] q;
qubit[1] flag;
U(pi/2, pi/2, -pi) q[0];
U(pi, 0, pi) flag[0];
cx q[0], flag[0];
U(0, 0, -pi/2) flag[0];
cx q[0], flag[0];
U(pi, pi/2, -pi/2) q[0];
U(0, 0, pi/2) flag[0];
barrier q[0], flag[0];
meas[0] = measure q[0];
meas[1] = measure flag[0];

